const {test}=require('node:test'),assert=require('node:assert/strict');
test('ten distinct town plans connect every household to services and carry smooth terrain',async()=>{const {TOWN_LAYOUTS,townLayout,layoutSites,townRoute,townElevation,townSurface}=await import('../town-life/layouts.mjs');const {districtRecipe}=await import('../district-scenes.js');assert.equal(Object.keys(TOWN_LAYOUTS).length,10);const shapes=new Set();for(const id of Object.keys(TOWN_LAYOUTS)){const d=townLayout(id),r=districtRecipe('town',id,41),sites=layoutSites(id);assert.equal(r.townLife.households.length,d.homes.length);shapes.add(JSON.stringify(d.paths));for(const h of d.homes){const route=townRoute(id,h.door,sites.school);assert.deepEqual(route.at(-1),sites.school);assert(route.length>1);}let min=Infinity,max=-Infinity;for(let x=-43;x<=43;x++)for(let z=-43;z<=43;z++){const h=townElevation(id,41,x,z);min=Math.min(min,h);max=Math.max(max,h);assert(Math.abs(h-townElevation(id,41,x+.1,z))/.1<.18);assert(Math.abs(h-townElevation(id,41,x,z+.1))/.1<.18);}assert(max-min>.5);assert.equal(townElevation(id,41,50,0),0);const p={center:{x:80,z:-50},rotation:2},h=townSurface(p,id,41,()=>10);assert(Math.abs(h(80,-50)-10-townElevation(id,41,0,0))<1e-9);}assert.equal(shapes.size,10);});
